head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gNdvNotiYn; //야간공지여부
scwin.gAcptNo;
scwin.gMainFormCd;
scwin.gFormVer;
scwin.pageSize = 50; //페이지 size
scwin.totalCnt = 0; //전체 row
scwin.pageNoCnt = 10; //page 번호 개수
scwin.vCurrPageNo = 0; //현재 선택된 페이지번호

scwin.key_uly_hist_yn = "Y";
scwin.key_prod_yn = "Y";
scwin.vScrenID = 'ULDSTF15400.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;
    scwin.gLdMktTp = js_market;
    $c.stf.setObjectValue(rdo_MKT_ID, 9);
    $c.stf.showObj(pnl_NDV_GB, false); //주야간구분 숨김

    //  기간 from~ to  셋팅	
    $c.stf.setObjectValue(cmb_PeriodTp, '1'); // 일주일전 날짜

    //  선물공시 보고서
    dts_FormCd.DataID = "/CodeAction.do?method=listFuturesFormCode" + "&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&For=R";
    dts_FormCd.Reset();

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !선물공시상세--;
목록검색;
클릭-- > function() {
    // 일자 체크
    if ($c.stf.getObjectValue(edt_FromDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_FromDate.focus();
        return;
    }

    // 일자 체크
    if ($c.stf.getObjectValue(edt_ToDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_ToDate.focus();
        return;
    }
    fn_Search();
} < !선물공시상세--;
클릭-- > function() {
    scwin.vCurrPageNo = 0;
    dts_DsclList_excel.removeAll();
    var url = "";
    var url_cond = "&FROM_DATE=" + $c.stf.getObjectValue(edt_FromDate) + "&TO_DATE=" + $c.stf.getObjectValue(edt_ToDate) + "&LAST_YN=" + scwin.getChkValue(chb_Last) + "&FORM_CD=" + $c.stf.getObjectValue(txb_FormCd) + "&FORM_NM=" + $c.stf.getObjectValue(txb_FormNm) + "&LD_MKT_TP=" + $c.stf.getObjectValue(rdo_MKT_ID) + "&NDV_GB=" + $c.stf.getObjectValue(rdo_NDV_GB) + "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&PAGENO=" + scwin.vCurrPageNo + "&PAGESIZE=" + scwin.pageSize + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    // 본문검색 키워드가 없을때 ... 일반 DB검색
    url = "/DisclosureSearch.do?method=pagingFuturesDsclSrch" + "&inputMessageId=DSCLDETAILCOND_IN" + "&outputMessageId=DSCLDETAILLIST_OUT";
    $c.cm.ShowWin(grd_Grid);
    dts_DsclList.DataID = encodeURI(url + url_cond);
    dts_DsclList.reset();
    $c.stf.showObj(grd_Grid, true);
};
scwin.PageNoCall = function(vPageNo) {
    //현재 선택한 페이지번호
    scwin.vCurrPageNo = vPageNo;
    var url = "/DisclosureSearch.do?method=pagingFuturesDsclSrch" + "&inputMessageId=DSCLDETAILCOND_IN" + "&outputMessageId=DSCLDETAILLIST_OUT" + "&FROM_DATE=" + $c.stf.getObjectValue(edt_FromDate) + "&TO_DATE=" + $c.stf.getObjectValue(edt_ToDate) + "&LAST_YN=" + scwin.getChkValue(chb_Last) + "&FORM_CD=" + $c.stf.getObjectValue(txb_FormCd) + "&FORM_NM=" + $c.stf.getObjectValue(txb_FormNm) + "&LD_MKT_TP=" + $c.stf.getObjectValue(rdo_MKT_ID) + "&NDV_GB=" + $c.stf.getObjectValue(rdo_NDV_GB) + "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&PAGENO=" + scwin.vCurrPageNo + "&PAGESIZE=" + scwin.pageSize + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    $c.cm.ShowWin(grd_Grid);
    dts_DsclList.DataID = encodeURI(url);
    dts_DsclList.reset();
};
scwin.getChkValue = function(obj) {
    //return (obj.checked) ? "Y" : "N";
    if (obj.checked == true) {
        return obj.getValue();
    } else {
        return "0";
    }
};
scwin.setChkValue = function(obj, booleanVal) {
    //return (obj.checked) ? "Y" : "N";
    obj.setValue(booleanVal);

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !선물공시상세검색--;
엑셀다운로드-- > function() {
    var url = "/DisclosureSearch.do?method=listFuturesDsclSrch" + "&inputMessageId=DSCLDETAILCOND_IN" + "&outputMessageId=DSCLDETAILLIST_OUT" + "&FROM_DATE=" + $c.stf.getObjectValue(edt_FromDate) + "&TO_DATE=" + $c.stf.getObjectValue(edt_ToDate) + "&LAST_YN=" + scwin.getChkValue(chb_Last) + "&FORM_CD=" + $c.stf.getObjectValue(txb_FormCd) + "&FORM_NM=" + $c.stf.getObjectValue(txb_FormNm) + "&LD_MKT_TP=" + $c.stf.getObjectValue(rdo_MKT_ID) + "&NDV_GB=" + $c.stf.getObjectValue(rdo_NDV_GB) + "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_07;
    dts_DsclList_excel.DataID = encodeURI(url);
    dts_DsclList_excel.reset();
};



// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gNdvNotiYn = dts_DsclList.getCellData(eval(obj), "NDV_NOTI_YN");
    scwin.gAcptNo = dts_DsclList.getCellData(eval(obj), "ACPT_NO");
    scwin.gMainFormCd = dts_DsclList.getCellData(eval(obj), "FORM_CD");
    scwin.gFormVer = dts_DsclList.getCellData(eval(obj), "FORM_VER");

    //alert("부모창:"+gAcptNo+","+gMainFormCd+","+ gFormVer+","+ gIsurCd);

};
scwin.fn_resetParam = function() {
    vCurrDate = $c.ut.cGetToday("yyyymmdd"); // 현재날짜

    $c.stf.setObjectValue(edt_FromDate, $c.ut.cGetMinusDate2(vCurrDate, 7));
    $c.stf.setObjectValue(edt_ToDate, vCurrDate);
    scwin.setChkValue(chb_Last, false);
    $c.stf.setObjectValue(rdo_MKT_ID, 9);
    $c.stf.showObj(pnl_NDV_GB, false); //주야간구분 숨김

};
scwin.btn_Search_onclick = function() {
    fn_CheckCond();
};
scwin.cmb_PerPage_OnSelChange = function() {
    var vPerPage = $c.cp.valueOfIndex(cmb_PerPage, "VALUE", cmb_PerPage.getSelectedIndex());
    scwin.pageSize = vPerPage;
    //alert(pageSize);	

};
scwin.dts_DsclList_OnLoadError = function() {
    $c.stf.alert_error(dts_DsclList);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_DsclList_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_Grid);
    if (dts_DsclList.errorMsg) {
        $c.win.alert(dts_DsclList.errorMsg);
    } else {
        //수정해야될 부분
        //데이터가 로드 되면 다음 내용을 처리 하도록 한다.
        //최초 조회인 경우 전체 row cnt를 구한다.

        //alert(vCurrPageNo +"= "+dts_DsclList.NameString(0,"TOTALCNT")+"= "+dts_DsclList.NameString(1,"TOTALCNT"));

        if (scwin.vCurrPageNo == 0) {
            scwin.vCurrPageNo = 1;
            scwin.totalCnt = dts_DsclList.getCellData(0, "TOTALCNT");
        }

        //alert(pageNoCnt +", "+pageSize+", "+totalCnt);
        //페이지번호개수,pagesize, 데이터전체cnt,패널id(page번호 표시),패널 width
        $c.stf.FillGridHeader(scwin.pageNoCnt, scwin.pageSize, scwin.totalCnt, panel_page, 743);
    }
};
scwin.dts_emp_OnLoadCompleted = function(rowcount) {
    $c.stf.setObjectValue(cmb_EmpList, js_emp_no);
};
scwin.dts_emp_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (scwin.gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_emp.getCellData(row, "dep_cd") == scwin.gDepCd ||
            dts_emp.getCellData(row, "dep_cd") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.dts_dep_OnLoadCompleted = function(rowcount) {
    $c.stf.setObjectValue(cmb_TeamList, js_dep_cd);
};
scwin.dts_DsclList_excel_OnLoadCompleted = function(rowcount) {
    $c.data.downloadGridViewExcel(grd_DsclList_excel, "선물공시검색  목록", "", "8");
};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.fn_setContnId(row);
    if (colid == "DOC_TITLE") {
        if (scwin.gNdvNotiYn == "Y") {
            //야간공지 상세조회 팝업 호출
            var url = "/dsclnightnoti/ULDSTF00002.gfm?NDV_NOTI_NO=" + scwin.gAcptNo + "&NOTI_PROCS_STAT_CD=30&POP_GB=R";
            var winTitle = "야간시장 공지 상세보기";
            $c.frame.path("/top").WinOpen("viewer" + scwin.gAcptNo, url, winTitle, 870, 500);
        } else {
            //2017-11-28 KBoY 비공개 첨부서류 볼 수 없음.
            $c.stf.fn_OpenDisclViewer(scwin.gAcptNo, "R", scwin.vScrenID);
        }
    }
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_FromDate, edt_ToDate);
};
scwin.rdo_MKT_ID_OnSelChange = function() {
    //시장구분이 파생상품인 경우
    if ($c.stf.getObjectValue(rdo_MKT_ID) == '3') {
        $c.stf.showObj(pnl_NDV_GB, true);
        $c.stf.setObjectValue(rdo_NDV_GB, "A"); //주야간구분 전체; 

    } else {
        $c.stf.showObj(pnl_NDV_GB, false);
    }
};
scwin.btn_Excel_onclick = function() {
    fn_ExcelDownload();
};
scwin.btn_Cancel_onclick = function() {
    scwin.fn_resetParam();
};
scwin.img_FromCal_onclick = function() {
    popUpCalendar2(edt_FromDate);
};
scwin.img_ToCal_onclick = function() {
    popUpCalendar2(edt_ToDate);
};
scwin.txb_FormCd_onblur = function() {
    if (txb_FormCd.getValue() == "") {
        txb_FormNm.setValue("");
    }
};
scwin.txb_FormNm_onblur = function() {
    if (txb_FormNm.getValue() == "") {
        txb_FormCd.setValue("");
    }
};
scwin.img_FindForm_onclick = async function() {
    // *** 셋팅할 필드명 정의를 아래처럼 해야함.
    // => 보고서명: txb_FormNm, 보고서코드 : txb_FormCd
    var url = "/common/ULDSTF91003_FUTURES.gfm";
    var winTitle = "공시제목선택 ";
    await $c.frame.CreateDialogFrame("FORMLIST", url, winTitle, 100, 10, 695, 575, "window");
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    //Grd_com_isur.style.display ="";
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onkeyup = function() {
    /*
    if (window.event.keyCode == 40) {
    		//아래화살표눌렀을때 그리드로 포커스
    		Grd_com_isur.Focus();
    }else{
    	if (window.event.keyCode ==13){
    		fn_com_Confirm_set();
    	}else{
    		fn_com_isur_nm(window.event.keyCode);
    	}
    }
    */
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearchFuturesOption(txb_isur_cd, txb_com_abbrv);
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.gform_onload = function() {
    $c.stf.showObj(grd_DsclList_excel, false);

    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();
    $c.stf.Combo_CBDataSet(cmb_PerPage);
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
    $c.cm.fn_com_isur_futures(txb_isur_cd, txb_com_abbrv);

    // 가우스헤더 셋팅
    dts_Dscl_Cond.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DSCLDETAILCOND_IN";
    dts_Dscl_Cond.reset();
};
